#include "cielo_recovery315.h"
#include <cassert>
using namespace cielo96::r315;
int main(){
 LatencyClass off,rgb,ch; for(int i=0;i<32;i++){off.observe(true,33,0,0);rgb.observe(true,97,0,0);ch.observe(true,282,0,0);} off.sample(250);rgb.sample(250);ch.sample(1000);assert(off.baseline==33&&rgb.baseline==97&&ch.baseline==282);for(int i=0;i<32;i++)off.observe(true,400,0,0);for(int i=0;i<3;i++){off.observe(true,400,0,0);off.sample(250);}assert(off.warning&&!rgb.warning);off.observe(false,0,0,0);off.sample(250);assert(off.warning);assert(assessNight(true,true,true,false,true,true)==NightPlan::WaitClock);assert(assessNight(true,true,true,true,true,true)==NightPlan::NightOffCandidate);assert(assessNight(true,true,true,true,true,false)==NightPlan::DayTarget);assert(assessNight(false,true,true,true,true,true)==NightPlan::NotApplicable);
NightProbe cancelled;assert(cancelled.start(true,true,true,true)==NightAction::ProbeMinimum);cancelled.cancel();cancelled.minimumResult();assert(cancelled.next(true,true,true)==NightAction::None);assert(cancelled.start(true,true,true,true)==NightAction::None);
StableLatency p,c;p.observe(true,2836,2000,223);for(int i=0;i<31;i++)p.observe(true,32,0,0);assert(!p.p95());p.observe(true,32,0,0);assert(p.p95()==32);for(int i=0;i<32;i++)c.observe(true,293,0,0);assert(calibrationReady(p.p95(),c.p95()));p.observe(false,7011,7000,0);assert(!p.p95());assert(!calibrationReady(7011,293));assert(restartRetryMs(true)==1800000);assert(restartRetryMs(false)==300000);NightProbe n;assert(n.start(true,false,true,true)==NightAction::None);assert(n.start(true,true,false,true)==NightAction::None);assert(n.start(true,true,true,true)==NightAction::ProbeMinimum);assert(n.start(true,true,true,true)==NightAction::None);n.minimumResult();assert(n.next(true,true,false)==NightAction::None);assert(n.next(true,true,true)==NightAction::Zero);n.zeroResult();assert(n.start(true,true,true,true)==NightAction::None);}
